{% for item in template_dict.file_open.comments %}
Item {{ item.file_name }} cannot be opened.
{% endfor %}

{% for item in template_dict.file_open.not_checked %}
Item {{ item.file_name }} is not checked by the script.
{% endfor %}

{% for item in template_dict.special_characters.comments %}
{{ item.file_name }} contains special characters
{% endfor %}

{% for item in template_dict.long_file_length.comments %}
{{ item.file_name }} file name contains more than 32 characters
{% endfor %}

{% for item in template_dict.file_ext.comments %}
{{ item.file_name }} does not have a file extension
{% endfor %}

{% for item in template_dict.typo.comments %}
{{ item }}
{% endfor %}

{% for item in template_dict.missing_field.researcher_id.comments %}   
    {% if item.researcher_id is none %}
        {{ item.authorName }} does not have a researcher id (e.g. ORCID)
    {% endif %}
{% endfor %}
